OR 1=1

    OR x.dept_id IN #{id}

OR x.owner_id=#{selfUserId})
AND x.dept_id=#{deptId}

mapper.select:
SELECT COUNT(*) periodAssetCount,
COALESCE(SUM(EXISTS(SELECT 1 FROM ca_borrow b WHERE b.asset_id=x.asset_id
    AND b.actual_pickup_time >= #{beginTime} AND b.actual_pickup_time < #{endTime}
    AND (1=0
        OR 1=1

            OR b.asset_dept_id IN #{id}

        OR b.applicant_user_id=#{selfUserId}
    ))),0) borrowedAssetCount,
COALESCE(SUM(EXISTS(SELECT 1 FROM ca_repair r WHERE r.asset_id=x.asset_id
    AND r.accept_time >= #{beginTime} AND r.accept_time < #{endTime}
    AND r.status IN ('1','2','3','4')
    AND (1=0
        OR 1=1

            OR r.asset_dept_id IN #{id}

        OR r.reporter_user_id=#{selfUserId}
    ))),0) repairedAssetCount
FROM (SELECT asset_id,dept_id,keeper_user_id owner_id,category_id,location_id,purchase_date
    FROM ca_asset WHERE registered_time < #{endTime}
    AND (scrapped_time IS NULL OR (scrapped_time > #{beginTime} AND scrapped_time > registered_time))) x
WHERE 1=1

SELECT dimension, SUM(x.kind='ASSET') assetCount, SUM(CASE WHEN x.kind='ASSET' THEN x.amount ELSE 0 END) registeredValue, SUM(x.kind='BORROW') borrowCount,SUM(x.kind='REPAIR') repairCount, SUM(CASE WHEN x.kind='COST' THEN x.amount ELSE 0 END) repairCost, SUM(x.kind='INVENTORY') inventoryCount, SUM(CASE WHEN x.kind='INVENTORY' THEN x.difference ELSE 0 END) inventoryDifferenceCount, SUM(x.kind='SCRAP') scrapCount FROM () x LEFT JOIN ca_category c ON c.category_id=x.category_id LEFT JOIN sys_dept d ON d.dept_id=x.dept_id WHERE x.event_time >= #{beginTime} AND x.event_time < #{endTime}
AND x.kind IN ('REPAIR','COST') AND x.kind=#{reportType}
GROUP BY ORDER BY dimension
